blobs.f2bd37b799d6:
﻿// synth-pad — a second use of the same "synth" module (see lead.k7x beside this file).
//
// Named for the lane it serves rather than after it: the lane "pad" is a node too now
// (nodes/pad.k7x), and one flat name space means one name, one node.
//
// Two nodes of one module are two separate chain steps with separate state: their
// params are merged independently over the module, and each saves its own opaque plugin
// blob (synth-pad.vstpreset here, lead.vstpreset next door), so tweaking one never touches
// the other or the module they share.
extends("@workspace/instruments/synth")
params({
  "Filter Freq": 40, // darker than the lead…
  Level: -12, // …and sitting further back
})
// Params merge per key, but a LIST is a scalar to the merge: restating `automations`
// replaces the inherited one outright. An empty list is how a node opts out of the
// filter sweep + detune LFO the module automates — the pad wants to sit still.
automations([])

blobs.f32e3d94f3e1:
// top
// The pattern's "Pad" part, as a GENERATED lane: the engine plays it from
// between
// algo/pattern.strudel while the transport rolls, which is why it says `strudel:` where an
// between
// authored lane says `events:`.
// between
//
// between
// Nothing here says what it carries — a lane is not typed, and each event leaves by the output
// between
// its own material fits. What makes these notes is that the pattern names no sample and that
// between
// graph.k7x wires `pad#midi:` to the instrument.
// between
extends("@meta/strudel-track")
// between
strudel("algo/pattern.strudel")
// between
// bottom

blobs.f354527fa31e:
﻿// lead — one USE of the "synth" module.
//
// A node is a `<name>.k7x` in the project's flat `nodes/` folder, and the FILE
// NAMES IT: chains say "lead" (see chains.k7x). It does not sit under the module it uses
// and does not mirror its folders — which module it uses is what `extends` says, and that
// is the only place the relationship is written down.
//
// So state only what THIS voice changes — the 4OSC plugin, the UI and the two automation
// curves all come from the synth module (which in turn extends @workspace/instruments/fourosc).
// The merge order is: fourosc -> synth -> this file, each winning per key.
extends("@workspace/instruments/synth")
params({
  "Filter Freq": 90, // brighter than the shared default — this one has to cut through
})

